+/** Checks resolved source imports against declarations in their owning workspaces. */
+export function checkWorkspaceDependencies(edges) {
+  const manifests = execFileSync("git", ["ls-files", "--cached", "--others", "--exclude-standard", "-z"], { cwd: root, encoding: "utf8" })
+    .split("\0")
+    .filter((file) => file.endsWith("/package.json") && !file.includes("node_modules/") && fs.existsSync(path.join(root, file)))
+    .map((file) => ({ directory: path.posix.dirname(file), ...JSON.parse(fs.readFileSync(path.join(root, file), "utf8")) }))
+    .filter((manifest) => manifest.name)
+    .sort((a, b) => b.directory.length - a.directory.length);
+  const owner = (file) => manifests.find((manifest) => file.startsWith(`${manifest.directory}/`));
+  const failures = new Map();
+  for (const edge of edges) {
+    if (/\.(test|spec|stories)\./.test(edge.from) || edge.from.includes("/tests/")) continue;
+    const source = owner(edge.from);
+    const target = owner(edge.to);
+    if (!source || !target || source.name === target.name) continue;
+    const declared = { ...source.dependencies, ...source.devDependencies, ...source.peerDependencies, ...source.optionalDependencies };
+    if (!declared[target.name]) failures.set(`${source.name}:${target.name}`, { ...edge, reason: `Undeclared workspace dependency: ${source.name} -> ${target.name}` });
+  }
+  return [...failures.values()];
+}
